#if UNITY_EDITOR
using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;using Oculus.Interaction;using Oculus.Interaction.HandGrab;using Oculus.Interaction.Input;using VRMaintenanceResearch.HandsLabQuest3.Runtime;
namespace VRMaintenanceResearch.HandsLabQuest3.Editor {
public static partial class HandsLabEditor {
static string inputCoverage;static bool inputSequenceComplete;static IEnumerator inputRoutine;static double inputDue,inputStart;static List<object> inputEvidence;static string inputFolder;static int videoFrame;static double nextVideo;static StreamWriter frameTimes;
static partial void TestCommand(string command){if(command=="sim_test")StartInputTest();else if(command=="sim_new_run"){StartInputTest();inputCoverage="IsolatedNewRun";inputRoutine=NewRunOnly();}else if(command=="sim_detail")SimDetail();else if(command=="save_lab"){Guard();Checks();EditorSceneManagerSave();}else if(command.StartsWith("regression_"))RegressionCommand(command);else throw new ArgumentException("Unknown HandsLab command: "+command);}
static void EditorSceneManagerSave(){UnityEditor.SceneManagement.EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());File.Copy(ScenePath,Out+"/MODIFIED_FILE.unity",true);}
static HandsLabSession Lab=>UnityEngine.Object.FindFirstObjectByType<HandsLabSession>();
static void Check(bool ok,string name){inputEvidence.Add(new{kind="ASSERT",name,passed=ok,elapsed=EditorApplication.timeSinceStartup-inputStart});if(!ok)throw new Exception(name);}
static void Mark(string name){inputEvidence.Add(new{kind="STEP",name,elapsed=EditorApplication.timeSinceStartup-inputStart});Lab.Logger.Record("TEST_STEP","handslab",name,"Active","Both",source:"Tester",inputSourceOverride:"SimulatedController");}
static void StartInputTest(){if(!EditorApplication.isPlaying)throw new Exception("Play Mode required");if(inputRoutine!=null)throw new Exception("Input test running");if(!simRunning)SimStart();Lab.actorSource="Tester";foreach(var b in Lab.panel.GetComponentsInChildren<UnityEngine.UI.Button>())if(!b.GetComponent<HandsLabPointerTrace>())b.gameObject.AddComponent<HandsLabPointerTrace>();inputStart=EditorApplication.timeSinceStartup;inputDue=inputStart;inputCoverage="FullInputSequence";inputSequenceComplete=false;inputEvidence=new List<object>();inputFolder=Out+"/input_run_"+DateTime.UtcNow.ToString("yyyyMMdd_HHmmss",System.Globalization.CultureInfo.InvariantCulture);Directory.CreateDirectory(inputFolder+"/frames");frameTimes=new StreamWriter(inputFolder+"/frames.csv");frameTimes.WriteLine("frame,elapsed_seconds,unity_frame_ms");videoFrame=0;nextVideo=inputStart;inputRoutine=InputSequence();EditorApplication.update+=TestTick;}
static void TestTick(){if(inputRoutine==null)return;if(!EditorApplication.isPlaying){FinishInput(false,"Play Mode ended");return;}double now=EditorApplication.timeSinceStartup;try{if(now>=nextVideo){nextVideo=now+.20;CaptureVideoFrame();}if(now<inputDue)return;if(!inputRoutine.MoveNext()){FinishInput(inputSequenceComplete,inputSequenceComplete?"All input assertions passed":"Iterator ended without completion marker");return;}inputDue=now+Convert.ToDouble(inputRoutine.Current);}catch(Exception e){inputEvidence.Add(new{kind="ERROR",error=e.ToString()});try{SimDetail();CaptureGame("input_failure");}catch(Exception diagnostic){inputEvidence.Add(new{kind="DIAGNOSTIC_ERROR",error=diagnostic.ToString()});}finally{FinishInput(false,e.Message);}}}
static void FinishInput(bool passed,string detail){EditorApplication.update-=TestTick;inputRoutine=null;leftGrip=rightGrip=leftTrigger=rightTrigger=0;frameTimes?.Flush();frameTimes?.Dispose();frameTimes=null;Write("input_result",new{passed,detail,coverage=inputCoverage,inputSource="SimulatedController",actorSource="Tester",hardwareVerified=false,folder=inputFolder,log=Lab?.Logger?.DirectoryPath,evidence=inputEvidence,elapsed=EditorApplication.timeSinceStartup-inputStart});}
static void CaptureVideoFrame(){string name="frame_"+videoFrame.ToString("D5")+".png";var c=Camera.main;var rt=new RenderTexture(960,600,24);var old=c.targetTexture;var active=RenderTexture.active;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;var tex=new Texture2D(960,600,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,960,600),0,0);tex.Apply();File.WriteAllBytes(inputFolder+"/frames/"+name,tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);}finally{c.targetTexture=old;RenderTexture.active=active;UnityEngine.Object.DestroyImmediate(rt);}frameTimes.WriteLine(name+","+(EditorApplication.timeSinceStartup-inputStart).ToString("F6",System.Globalization.CultureInfo.InvariantCulture)+","+(Time.unscaledDeltaTime*1000).ToString("F4",System.Globalization.CultureInfo.InvariantCulture));frameTimes.Flush();videoFrame++;}
static HandGrabInteractor Grabber(int side){return Lab.guards[side].interactionsRoot.GetComponentsInChildren<HandGrabInteractor>(true).First(i=>i.name=="ControllerHandGrabInteractor");}
static void AimWrist(int side,HandGrabPose pose){var hand=Grabber(side);var relative=pose.RelativePose;var targetPosition=pose.RelativeTo.TransformPoint(relative.position);var targetRotation=pose.RelativeTo.rotation*relative.rotation;var delta=targetRotation*Quaternion.Inverse(hand.WristPoint.rotation);if(side==0){leftRotation=delta*leftRotation;leftPosition+=targetPosition-hand.WristPoint.position;}else{rightRotation=delta*rightRotation;rightPosition+=targetPosition-hand.WristPoint.position;}}
static void ApproachPalm(int side,HandsLabObject item){var palm=(item.stableId=="handslab.pinch_stone"?Grabber(side).PinchPoint:Grabber(side).PalmPoint).position;var colliders=item.GetComponentsInChildren<Collider>().Where(c=>c.enabled&&!c.isTrigger).ToArray();var c=colliders.OrderBy(x=>(x.ClosestPoint(palm)-palm).sqrMagnitude).First();var contact=c.ClosestPoint(palm);var inward=(c.bounds.center-contact).normalized*.018f;var delta=contact+inward-palm;if(side==0)leftPosition+=delta;else rightPosition+=delta;}
    static HandGrabPose PickPose(HandsLabObject item,int side){var handedness=side==0?Handedness.Left:Handedness.Right;return item.GetComponentsInChildren<HandGrabPose>(true).Where(p=>p.HandPose.Handedness==handedness&&(item.stableId!="handslab.grip_mug"||p.RelativePose.position.x<-.1f)).OrderBy(p=>Vector3.Distance(p.transform.position,Grabber(side).WristPoint.position)).First();}
static void AimUi(int side,UnityEngine.UI.Button button=null){var ray=Lab.guards[side].interactionsRoot.GetComponentsInChildren<RayInteractor>(true).First(r=>r.name=="ControllerRayInteractor");var rect=(button?button:Lab.panel.TestButton).GetComponent<RectTransform>();var dir=(rect.TransformPoint(rect.rect.center)-ray.Origin).normalized;var delta=Quaternion.FromToRotation(ray.Forward,dir);if(side==0)leftRotation=delta*leftRotation;else rightRotation=delta*rightRotation;}
static void CaptureContact(string name,HandsLabObject item){var go=new GameObject("HandsLabEvidenceCamera"){hideFlags=HideFlags.HideAndDontSave};try{var c=go.AddComponent<Camera>();c.CopyFrom(Camera.main);c.enabled=false;c.fieldOfView=50;c.transform.position=item.transform.position+new Vector3(-.22f,.16f,-.22f);c.transform.LookAt(item.transform.position);CaptureGame(name,c);}finally{UnityEngine.Object.DestroyImmediate(go);}}
    static int PressCount(string directory){using(var stream=new FileStream(Path.Combine(directory,"events.jsonl"),FileMode.Open,FileAccess.Read,FileShare.ReadWrite))using(var reader=new StreamReader(stream)){int count=0;string line;while((line=reader.ReadLine())!=null)if((string)Newtonsoft.Json.Linq.JObject.Parse(line)["event"]=="PRESS")count++;return count;}}
    static System.Collections.Generic.IEnumerable<double> ClickInput(int side,UnityEngine.UI.Button button){for(int i=0;i<20;i++){AimUi(side,button);yield return .05d;}yield return .75d;if(side==0)leftTrigger=1;else rightTrigger=1;yield return .4d;if(side==0)leftTrigger=0;else rightTrigger=0;yield return .8d;}
    static IEnumerator NewRunOnly(){yield return 2d;var previous=Lab.Logger;rightPosition=new Vector3(.25f,1.10f,.28f);rightRotation=Quaternion.identity;leftPosition=new Vector3(-.25f,1.10f,.28f);leftRotation=Quaternion.identity;yield return .5d;foreach(var d in ClickInput(1,Lab.panel.TestButton))yield return d;foreach(var d in ClickInput(1,Lab.panel.NewRunButton))yield return d;Check(previous.DataComplete&&Lab.Logger!=previous,"new run only via input");inputSequenceComplete=true;}
 static Quaternion[] ThumbPose(){return Lab.GetComponentsInChildren<SkinnedMeshRenderer>(true).Where(r=>r.enabled&&r.gameObject.activeInHierarchy).SelectMany(r=>r.bones).Where(b=>b.name.IndexOf("thumb",StringComparison.OrdinalIgnoreCase)>=0).Select(b=>b.localRotation).ToArray();}
 static IEnumerator InputSequence(){
 yield return 2d;
 Check(Lab.guards.All(g=>g.TrackingValid&&g.InteractionsAllowed),"two simulated controller providers valid and neutral gate open");
 Check(Lab.Logger!=null&&Lab.Logger.State==Logging.HandsLabLogState.Active,"logger active");
 Mark("open hands");CaptureGame("input_open");yield return 1d;
 leftGrip=rightGrip=leftTrigger=rightTrigger=1;Mark("grip and trigger without capacitive touch");yield return 1.2d;CaptureGame("input_controller_pressed");var thumbBefore=ThumbPose();
 leftThumbTouch=rightThumbTouch=true;Mark("primary capacitive touch closes thumb via standard SDK mapping");yield return 1d;var thumbAfter=ThumbPose();Check(thumbBefore.Length>0&&thumbBefore.Length==thumbAfter.Length&&thumbBefore.Zip(thumbAfter,(a,b)=>Quaternion.Angle(a,b)).Max()>5,"capacitive primary touch changes displayed thumb pose");CaptureGame("input_fist");
 leftThumbTouch=rightThumbTouch=false;leftTrigger=rightTrigger=0;Mark("grip with trigger released pointing");yield return 1.2d;CaptureGame("input_point");leftGrip=rightGrip=0;yield return 1d;
 var mug=Lab.objects.Single(o=>o.stableId=="handslab.grip_mug");var stone=Lab.objects.Single(o=>o.stableId=="handslab.pinch_stone");var pose=PickPose(mug,1);
 Mark("right hand approaches SDK authored handle grasp via input pose");for(int i=0;i<24;i++){AimWrist(1,pose);yield return .06d;}for(int i=0;i<12;i++){ApproachPalm(1,mug);yield return .08d;}rightGrip=1;yield return 1d;Check(mug.IsHeld,"right grip selects mug handle through ISDK");rightPosition+=Vector3.up*.15f;yield return .6d;CaptureGame("input_mug_held");
 var mugBefore=mug.transform.position;var mugRotation=mug.transform.rotation;rightPosition+=new Vector3(0,.15f,-.03f);rightRotation=Quaternion.Euler(0,35,15)*rightRotation;yield return 1d;
 Check(mug.IsHeld&&Vector3.Distance(mugBefore,mug.transform.position)>.08f&&Quaternion.Angle(mugRotation,mug.transform.rotation)>15,"actual selected mug translated and rotated by SDK");CaptureGame("input_mug_rotated");CaptureContact("input_mug_handle_contact",mug);
 rightGrip=0;yield return 1d;Check(!mug.IsHeld,"right release unselects mug");CaptureGame("input_mug_released");rightPosition=new Vector3(.25f,1.10f,.28f);rightRotation=Quaternion.identity;
 pose=PickPose(stone,0);Mark("left hand approaches authored pinch grasp via input pose");for(int i=0;i<24;i++){AimWrist(0,pose);yield return .06d;}for(int i=0;i<12;i++){ApproachPalm(0,stone);yield return .08d;}leftGrip=1;yield return 1d;Check(stone.IsHeld,"left controller grip selects distinct authored pinch pose");leftPosition+=new Vector3(0,.20f,-.04f);yield return .8d;CaptureGame("input_stone_held");CaptureContact("input_stone_pinch_contact",stone);
 foreach(var delay in ClickInput(1,Lab.panel.TestButton))yield return delay;
 Check(stone.IsHeld,"other hand UI preserves held stone");Check(PressCount(Lab.Logger.DirectoryPath)==1,"one ray trigger click emits exactly one semantic PRESS while other hand holds");CaptureGame("input_other_hand_ui");
 Mark("tracking loss while left holds stone");simTracking=false;yield return 1d;Check(!stone.IsHeld&&Lab.guards.All(g=>!g.InteractionsAllowed),"tracking loss system releases and blocks input");CaptureGame("input_tracking_lost");simTracking=true;yield return 1d;Check(!stone.IsHeld&&!Lab.guards[0].InteractionsAllowed,"restored tracking with grip held does not auto-regrab");leftGrip=0;yield return 1d;Check(Lab.guards.All(g=>g.InteractionsAllowed),"neutral after recovery reopens gates");CaptureGame("input_recovered");
 Mark("reset objects through ray UI");foreach(var delay in ClickInput(1,Lab.panel.ResetButton))yield return delay;Check(Lab.objects.All(o=>!o.IsHeld),"UI reset clears ownership");yield return 1d;
 pose=PickPose(stone,0);for(int i=0;i<24;i++){AimWrist(0,pose);yield return .06d;}for(int i=0;i<12;i++){ApproachPalm(0,stone);yield return .08d;}leftGrip=1;yield return .8d;Check(stone.IsHeld,"left regrabs after tracking recovery");leftPosition+=Vector3.up*.15f;yield return .4d;
 pose=PickPose(mug,1);for(int i=0;i<24;i++){AimWrist(1,pose);yield return .06d;}for(int i=0;i<12;i++){ApproachPalm(1,mug);yield return .08d;}rightGrip=1;yield return 1d;Check(stone.IsHeld&&mug.IsHeld,"two hands own separate objects simultaneously");rightPosition+=Vector3.up*.15f;yield return .6d;CaptureGame("input_two_hands_held");
 int pressBefore=PressCount(Lab.Logger.DirectoryPath);leftTrigger=rightTrigger=1;yield return .6d;leftTrigger=rightTrigger=0;yield return .5d;Check(PressCount(Lab.Logger.DirectoryPath)==pressBefore,"trigger input while holding emits no UI PRESS");leftGrip=rightGrip=0;yield return 1d;Check(Lab.objects.All(o=>!o.IsHeld),"two releases clear independent ownership");
 rightPosition=new Vector3(.25f,1.10f,.28f);rightRotation=Quaternion.identity;leftPosition=new Vector3(-.25f,1.10f,.28f);leftRotation=Quaternion.identity;yield return .5d;
 Mark("test fixture inserts physical wall between ray and UI");var wall=GameObject.CreatePrimitive(PrimitiveType.Cube);wall.name="Tester_UI_Occlusion_Wall";wall.transform.position=new Vector3(0,1.12f,.49f);wall.transform.localScale=new Vector3(.8f,.55f,.025f);yield return .5d;pressBefore=PressCount(Lab.Logger.DirectoryPath);foreach(var delay in ClickInput(1,Lab.panel.TestButton))yield return delay;Check(PressCount(Lab.Logger.DirectoryPath)==pressBefore,"plain physics wall blocks ray UI PRESS");CaptureGame("input_wall_blocks_ui");UnityEngine.Object.Destroy(wall);yield return .6d;
 foreach(var delay in ClickInput(1,Lab.panel.TestButton))yield return delay;Check(PressCount(Lab.Logger.DirectoryPath)==pressBefore+1,"ray UI recovers after wall removal without duplicate PRESS");
 var previousLogger=Lab.Logger;Mark("new run through ray UI");foreach(var delay in ClickInput(1,Lab.panel.NewRunButton))yield return delay;Check(previousLogger.DataComplete&&Lab.Logger!=previousLogger&&Lab.Logger.DirectoryPath!=previousLogger.DirectoryPath,"UI new run flushes prior writer before unique next run");inputEvidence.Add(new{kind="COMPLETED_RUN",directory=previousLogger.DirectoryPath});Check(Lab.objects.All(o=>!o.IsHeld),"new run has no stale held object");CaptureGame("input_new_run");Mark("completed simulated-controller sequence; hand tracking hardware not exercised");inputSequenceComplete=true;
 }
 static object ContactDetail(HandGrabInteractor i){var so=new SerializedObject(i);var grip=so.FindProperty("_gripCollider").objectReferenceValue as Collider;var pinch=so.FindProperty("_pinchCollider").objectReferenceValue as Collider;var registry=HandGrabInteractable.Registry.List(i).ToArray();return new{name=i.name,state=i.State.ToString(),registry=registry.Select(x=>x.name).ToArray(),apiId=i.HandGrabApi.GetInstanceID(),apiHand=(i.HandGrabApi.Hand as Component)?.name,apiHandId=(i.HandGrabApi.Hand as Component)?.GetInstanceID(),handId=(i.Hand as Component)?.GetInstanceID(),handTracking=i.HandGrabApi.Hand.IsTrackedDataValid,supported=i.SupportedGrabTypes.ToString(),pinchFingers=i.HandGrabApi.HandPinchGrabbingFingers().ToString(),palmFingers=i.HandGrabApi.HandPalmGrabbingFingers().ToString(),middlePinch=i.HandGrabApi.GetFingerPinchStrength(HandFinger.Middle),middlePalm=i.HandGrabApi.GetFingerPalmStrength(HandFinger.Middle),volumes=new[]{grip,pinch}.Where(c=>c).Select(c=>new{c.name,c.enabled,c.isTrigger,active=c.gameObject.activeInHierarchy,position=c.transform.position.ToString("F4"),bounds=c.bounds.size.ToString("F4")}).ToArray(),objects=Lab.objects.SelectMany(o=>o.GetComponentsInChildren<HandGrabInteractable>(true)).Where(h=>h.isActiveAndEnabled).Select(h=>new{h.name,h.enabled,active=h.gameObject.activeInHierarchy,types=h.SupportedGrabTypes.ToString(),registered=registry.Contains(h),colliders=h.Colliders.Select(c=>new{c.name,c.enabled,c.isTrigger,active=c.gameObject.activeInHierarchy,palm=grip&&Physics.ComputePenetration(grip,grip.transform.position,grip.transform.rotation,c,c.transform.position,c.transform.rotation,out _,out _),pinch=pinch&&Physics.ComputePenetration(pinch,pinch.transform.position,pinch.transform.rotation,c,c.transform.position,c.transform.rotation,out _,out _)}).ToArray()}).ToArray()};}
    static void SimDetail(){var l=Lab;Write("sim_detail",new{controllers=l.GetComponentsInChildren<Controller>(true).Select(c=>new{c.name,c.IsConnected,c.IsPoseValid,grip=c.ControllerInput.Grip,gripButton=c.ControllerInput.GripButton,trigger=c.ControllerInput.Trigger,triggerButton=c.ControllerInput.TriggerButton}).ToArray(),injectors=l.GetComponentsInChildren<Oculus.Interaction.GrabAPI.ControllerPinchInjector>(true).Select(c=>new{c.name,path=AnimationUtility.CalculateTransformPath(c.transform,l.transform),active=c.isActiveAndEnabled,controller=(new SerializedObject(c).FindProperty("_controller").objectReferenceValue as Component)?.name,controllerId=new SerializedObject(c).FindProperty("_controller").objectReferenceValue?.GetInstanceID(),api=new SerializedObject(c).FindProperty("_handGrabAPI").objectReferenceValue?.GetInstanceID(),grip=(new SerializedObject(c).FindProperty("_controller").objectReferenceValue as IController)?.ControllerInput.Grip}).ToArray(),contacts=new[]{ContactDetail(Grabber(0)),ContactDetail(Grabber(1))},head=l.head.transform.position.ToString("F4"),trackingSpace=l.trackingSpace.position.ToString("F4"),cameraRotation=l.head.transform.eulerAngles.ToString("F3"),guards=l.guards.Select(g=>new{side=g.side.ToString(),mode=g.Mode.ToString(),g.TrackingValid,g.InteractionsAllowed}),grabs=l.guards.SelectMany(g=>g.interactionsRoot.GetComponentsInChildren<HandGrabInteractor>(true)).Select(i=>new{i.name,active=i.isActiveAndEnabled,state=i.State.ToString(),selected=i.IsGrabbing,wrist=i.WristPoint?i.WristPoint.position.ToString("F4"):null,palm=i.PalmPoint?i.PalmPoint.position.ToString("F4"):null,pinch=i.PinchPoint?i.PinchPoint.position.ToString("F4"):null,i.FingersStrength,i.WristStrength,target=i.TargetInteractable?.ToString()}).ToArray(),renderers=l.GetComponentsInChildren<SkinnedMeshRenderer>(true).Where(r=>r.gameObject.activeInHierarchy&&r.enabled).Select(r=>new{r.name,position=r.transform.position.ToString("F4"),bounds=r.bounds.size.ToString("F4"),bones=r.bones.Length}).ToArray()});}
}}
namespace VRMaintenanceResearch.HandsLabQuest3.Editor { public sealed class HandsLabPointerTrace:MonoBehaviour,UnityEngine.EventSystems.IPointerDownHandler,UnityEngine.EventSystems.IPointerUpHandler,UnityEngine.EventSystems.IPointerClickHandler{
void Trace(string phase,UnityEngine.EventSystems.PointerEventData e){Debug.Log("HANDSLAB_POINTER "+phase+" "+name+" pointer="+e.pointerId+" eligible="+e.eligibleForClick+" press="+e.pointerPress?.name+" over="+e.pointerCurrentRaycast.gameObject?.name+" pos="+e.position+" interactable="+GetComponent<UnityEngine.UI.Button>().interactable);}
public void OnPointerDown(UnityEngine.EventSystems.PointerEventData e)=>Trace("DOWN",e);public void OnPointerUp(UnityEngine.EventSystems.PointerEventData e)=>Trace("UP",e);public void OnPointerClick(UnityEngine.EventSystems.PointerEventData e)=>Trace("CLICK",e);
}}
